  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"tahquitz-canyon-trail","name":"Tahquitz Canyon Trail","city":"Palm Springs","blurb":"1.8-mile strenuous loop to a waterfall on Agua Caliente tribal land, with ranger-led hikes. Admission fee; open daily 7:30 AM to 5 PM Oct. 1 to July 5, then Fri to Sun only. Bring water; there's little shade.","phone":"(760) 323-6018","url":"https://www.tahquitzcanyon.com/hours","address":"500 W Mesquite Ave, Palm Springs, CA 92264"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"palm-canyon-trail","name":"Palm Canyon Trail (Indian Canyons)","city":"Palm Springs","blurb":"The largest fan palm oasis in North America, on Agua Caliente tribal land. Walk the main oasis and return on the Victor Trail for a 1 to 2 hour hike, or follow Palm Canyon for miles. Admission fee at the Indian Canyons toll gate.","phone":"(760) 323-6018","url":"https://www.indian-canyons.com/hours","address":"38520 S Palm Canyon Dr, Palm Springs, CA 92264"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"andreas-canyon-trail","name":"Andreas Canyon Trail (Indian Canyons)","city":"Palm Springs","blurb":"Easy 1.2-mile loop along shady Andreas Creek through a palm oasis in the Indian Canyons. Admission fee at the toll gate.","phone":"(760) 323-6018","url":"https://www.indian-canyons.com/hours","address":"38520 S Palm Canyon Dr, Palm Springs, CA 92264"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"murray-canyon-trail","name":"Murray Canyon Trail (Indian Canyons)","city":"Palm Springs","blurb":"Moderate 4.7-mile loop, about 3 hours and 450 feet of climb, through palm-lined Murray Canyon in the Indian Canyons. Admission fee at the toll gate.","phone":"(760) 323-6018","url":"https://www.indian-canyons.com/hours","address":"38520 S Palm Canyon Dr, Palm Springs, CA 92264"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"museum-trail","name":"Museum Trail","city":"Palm Springs","blurb":"Steep, rocky climb from behind the Palm Springs Art Museum to picnic tables with views over downtown. Free. Connects to the North Lykken Trail.","url":"https://visitpalmsprings.com/blog/post/hiking-guide/","address":"Palm Springs Art Museum north lot, 101 N Museum Dr, Palm Springs, CA 92262"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"north-lykken-trail","name":"North Lykken Trail","city":"Palm Springs","blurb":"Hard climb of about 4.5 miles round trip from the west end of Ramon Road, ending at the Art Museum where it meets the Museum Trail. No shade. Free.","url":"https://visitpalmsprings.com/blog/post/hiking-guide/","address":"West end of Ramon Rd, Palm Springs, CA 92264"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"south-lykken-trail","name":"South Lykken Trail","city":"Palm Springs","blurb":"Long ridge trail of about 7 miles between Mesquite Avenue and South Palm Canyon Drive, with big views over Palm Springs. Free.","url":"https://visitpalmsprings.com/blog/post/hiking-guide/","address":"Mesquite Ave near Tahquitz Canyon, Palm Springs, CA 92264"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"long-valley-loop-trail","name":"Long Valley Loop Trail","city":"Palm Springs","blurb":"Easy 1.2-mile loop at the top of the Palm Springs Aerial Tramway, with overlooks of the whole valley out to the Salton Sea. Tram ticket required. Cooler than the desert floor.","url":"https://www.blm.gov/sites/blm.gov/files/programs-nlcs-ca-santa-rosa-san-jacinto-national-monument-hiking-SanJac.pdf","address":"Palm Springs Aerial Tramway, 1 Tram Way, Palm Springs, CA 92262"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"san-jacinto-peak-via-tramway","name":"San Jacinto Peak via the Tramway","city":"Palm Springs","blurb":"The easiest route to the 10,834-foot summit: about 11 miles round trip and 2,500 feet of climb from the Tram's Mountain Station. Strenuous. Get a free wilderness permit at the state park ranger station.","url":"https://www.blm.gov/sites/blm.gov/files/programs-nlcs-ca-santa-rosa-san-jacinto-national-monument-hiking-SanJac.pdf","address":"Palm Springs Aerial Tramway, 1 Tram Way, Palm Springs, CA 92262"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"art-smith-trail","name":"Art Smith Trail","city":"Palm Desert","blurb":"Signature 8.3-mile National Monument trail with 1,465 feet of climb through hidden canyons and palm oases. Strenuous. Bighorn sheep are often seen. No dogs.","phone":"(760) 862-9984","url":"https://www.blm.gov/visit/santa-rosa-and-san-jacinto-mountains-national-monument","address":"Hwy 74, 4 miles south of Hwy 111 (past the National Monument Visitor Center), Palm Desert, CA 92260"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"randall-henderson-trail","name":"Randall Henderson Trail","city":"Palm Desert","blurb":"Easy 2.4-mile loop with about 400 feet of climb at the National Monument Visitor Center. A good first desert hike, with a plant guide from the visitor center. No dogs.","phone":"(760) 862-9984","url":"https://www.blm.gov/visit/santa-rosa-and-san-jacinto-mountains-national-monument","address":"National Monument Visitor Center, 51-500 Hwy 74, Palm Desert, CA 92260"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"hopalong-cassidy-trail","name":"Hopalong Cassidy Trail","city":"Palm Desert","blurb":"Strenuous 8.3-mile rollercoaster trail above Palm Desert, from Painters Path to the Art Smith Trail, passing the lighted cross. Dogs allowed only from the Gabby Hayes junction to the cross.","phone":"(760) 862-9984","url":"https://www.blm.gov/visit/santa-rosa-and-san-jacinto-mountains-national-monument","address":"Painters Path, behind the Desert Crossing shopping center, Palm Desert, CA 92260"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"homestead-trail-to-the-cross","name":"Homestead Trail to the Cross","city":"Palm Desert","blurb":"Popular half-mile climb of 733 feet from Homme-Adams Park that connects to the Hopalong Cassidy Trail and the cross on top of the mountain. Moderate. Dogs allowed.","phone":"(760) 862-9984","url":"https://www.blm.gov/visit/santa-rosa-and-san-jacinto-mountains-national-monument","address":"Homme-Adams Park, 72-500 Thrush Rd, Palm Desert, CA 92260"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"bump-and-grind-trail","name":"Bump and Grind Trail","city":"Palm Desert","blurb":"The most popular workout trail in the National Monument: 1.1 miles and 523 feet of climb, or a 3-mile loop with the Hopalong Cassidy and Herb Jeffries trails. Moderate. No dogs.","phone":"(760) 862-9984","url":"https://www.blm.gov/visit/santa-rosa-and-san-jacinto-mountains-national-monument","address":"Mike Schuler Trailhead, Painters Path, Palm Desert, CA 92260"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"gabby-hayes-trail","name":"Gabby Hayes Trail","city":"Palm Desert","blurb":"Short, easy trail from Cahuilla Hills Park that links to a 2.3-mile loop with the Hopalong Cassidy and Herb Jeffries trails, or up to the cross. Dogs allowed to the Hopalong Cassidy junction.","phone":"(760) 862-9984","url":"https://www.blm.gov/visit/santa-rosa-and-san-jacinto-mountains-national-monument","address":"Cahuilla Hills Park, 72700 Tierra Del Oro, Palm Desert, CA 92260"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"bighorn-overlook-trail","name":"Bighorn Overlook Trail","city":"Rancho Mirage","blurb":"Easy 0.6-mile climb from Rancho Mirage City Hall to a shaded picnic table and a panoramic view. Connects to the Jack Rabbit Trail. Dogs allowed.","url":"https://www.blm.gov/visit/santa-rosa-and-san-jacinto-mountains-national-monument","address":"Rancho Mirage City Hall upper lot, Frank Sinatra Dr off Hwy 111, Rancho Mirage, CA 92270"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"chuckwalla-trail","name":"Chuckwalla Trail","city":"Rancho Mirage","blurb":"Easy 2.2-mile loop carved into the hillside from the Roadrunner trailhead, a favorite with trail runners and mountain bikers. Dogs allowed on a leash.","url":"https://www.blm.gov/visit/santa-rosa-and-san-jacinto-mountains-national-monument","address":"Roadrunner Trailhead, across Frank Sinatra Dr from Rancho Mirage City Hall, Rancho Mirage, CA 92270"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"bear-creek-trail","name":"Bear Creek Trail","city":"La Quinta","blurb":"4.75-mile paved path from Eisenhower Drive and Calle Tampico along the Cove to the Fred Wolff Nature Preserve and the Cove Oasis Trailhead. Easy and flat, with mountain views.","url":"https://www.laquintaca.gov/business/community-resources/parks-and-trails/bear-creek-trail","address":"Eisenhower Dr and Calle Tampico, La Quinta, CA 92253"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"boo-hoff-trail","name":"Boo Hoff Trail","city":"La Quinta","blurb":"La Quinta's classic mountain hike, starting at the Cove Oasis Trailhead and climbing into the Santa Rosa Mountains. The trailhead has picnic tables, a water fountain and a bronze relief trail map.","url":"https://www.laquintaca.gov/business/community-resources/parks-and-trails/cove-oasis-trailhead","address":"Cove Oasis Trailhead, Calle Tecate, La Quinta, CA 92253"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"cove-to-lake-trail","name":"Cove to Lake Trail","city":"La Quinta","blurb":"Moderate 4.8-mile round trip with 330 feet of climb, over a saddle from the Cove and down a desert wash to Lake Cahuilla. 3 to 4 hours. No dogs.","url":"https://www.laquintaca.gov/visit/hiking-trails-986","address":"Cove Oasis Trailhead, Calle Tecate, La Quinta, CA 92253"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"thousand-palms-oasis-preserve","name":"Thousand Palms Oasis Preserve","city":"Thousand Palms","blurb":"Start of the Coachella Valley Preserve's 25-plus miles of trails, including the McCallum Trail along the San Andreas Fault. Free. Open Sat and Sun 7 AM to 3 PM May through October. No pets, and no on-site parking right now.","url":"https://www.cnlm.org/portfolio_page/thousand-palms-oasis-preserve-coachella-valley-preserve/","address":"Thousand Palms Canyon Rd, Thousand Palms, CA 92276"},
  {"category":"Outdoors","service":"Hiking trails","public":true,"slug":"whitewater-preserve","name":"Whitewater Preserve","city":"Whitewater","blurb":"Free Wildlands Conservancy preserve in Whitewater Canyon, northwest of Palm Springs, with hiking trails in the canyon. Open 8 AM to 5 PM; reservations recommended.","phone":"(760) 325-7222","url":"https://wildlandsconservancy.org/preserve/whitewater-preserve/","address":"9160 Whitewater Canyon Rd, Whitewater, CA 92282"}
